parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "area_solicitante": { "type": "string", "description": "Área interna que solicita (ej. Perforación, Mantenimiento). Cadena vacía si no se informa." },
    "tipo": { "type": "string", "description": "Bien o Servicio. Cadena vacía si no se puede determinar." },
    "descripcion": { "type": "string", "description": "Descripción técnica normalizada del ítem, sin inventar especificaciones. Cadena vacía si no se informa." },
    "cantidad": { "type": "number", "description": "Cantidad numérica solicitada. 0 si no se informa." },
    "unidad": { "type": "string", "description": "Unidad de medida (un, m, kg, l, rollo, par, etc.). Cadena vacía si no se informa ni es inferible sin ambigüedad." },
    "destino": { "type": "string", "description": "Yacimiento, pozo o base de destino. Cadena vacía si no se informa." },
    "prioridad": { "type": "string", "description": "Normal, Urgente o Crítica. Normal si el usuario no menciona urgencia." },
    "justificacion": { "type": "string", "description": "Motivo explícito del pedido o de la urgencia, tal como lo expresa el usuario. Cadena vacía si no se informa." },
    "observaciones": { "type": "string", "description": "Supuestos o interpretaciones realizadas al extraer. Cadena vacía si no hubo." },
    "nombre_solicitante": { "type": "string", "description": "Nombre de pila de la persona que escribe, solo si se presenta (ej. 'soy Juan'). Cadena vacía si no lo dice." }
  },
  "required": ["area_solicitante", "tipo", "descripcion", "cantidad", "unidad", "destino", "prioridad", "justificacion", "observaciones", "nombre_solicitante"]
}
